const decode=s=>Uint8Array.from(atob(s.replace(/-/g,'+').replace(/_/g,'/')),c=>c.charCodeAt(0));
export async function unlockSeed(payload,encodedKey){if(!payload||payload.version!==1||typeof encodedKey!=='string'||!/^[A-Za-z0-9_-]{43}$/.test(encodedKey))throw Error('Özel açılış bağlantısı geçersiz.');const key=await crypto.subtle.importKey('raw',decode(encodedKey),{name:'AES-GCM'},false,['decrypt']);let bytes;try{bytes=await crypto.subtle.decrypt({name:'AES-GCM',iv:decode(payload.iv)},key,decode(payload.data))}catch{throw Error('Veriler açılamadı. Size gönderilen özel bağlantının tamamını kullanın.')}return JSON.parse(new TextDecoder().decode(bytes))}
